-- READ-ONLY bounded episode evidence for 2019-10-26/27 source-present 65-minute gap.
WITH targets AS (SELECT 1572134100 target_time UNION ALL SELECT 1572134400 target_time UNION ALL SELECT 1572134700 target_time UNION ALL SELECT 1572135000 target_time UNION ALL SELECT 1572135300 target_time UNION ALL SELECT 1572135600 target_time UNION ALL SELECT 1572135900 target_time UNION ALL SELECT 1572136200 target_time UNION ALL SELECT 1572136500 target_time UNION ALL SELECT 1572136800 target_time UNION ALL SELECT 1572137100 target_time UNION ALL SELECT 1572137400 target_time UNION ALL SELECT 1572137700 target_time UNION ALL SELECT 1572138000 target_time)
SELECT t.target_time, a.usUnits old_units, a.`interval` old_interval, b.usUnits wh_units, b.`interval` wh_interval, a.`outTemp` old_outTemp, b.`outTemp` wh_outTemp, a.`outHumidity` old_outHumidity, b.`outHumidity` wh_outHumidity, a.`rain` old_rain, b.`rain` wh_rain, a.`rainRate` old_rainRate, b.`rainRate` wh_rainRate, a.`windSpeed` old_windSpeed, b.`windSpeed` wh_windSpeed, a.`windGust` old_windGust, b.`windGust` wh_windGust, a.`windDir` old_windDir, b.`windDir` wh_windDir, a.`barometer` old_barometer, b.`barometer` wh_barometer, c.dateTime reconstruction_row, c.outTemp reconstruction_outTemp, c.outHumidity reconstruction_outHumidity, (SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes h WHERE h.target_time=t.target_time) change_events, (SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes h WHERE h.target_time=t.target_time AND h.variable='outTemp') outTemp_events
FROM targets t LEFT JOIN `old_weewx`.archive a ON a.dateTime=t.target_time LEFT JOIN `weewx_WH1080`.archive b ON b.dateTime=t.target_time LEFT JOIN loucka_reconstruction.archive c ON c.dateTime=t.target_time ORDER BY t.target_time;
